def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    if n >= 2:
        if (history[-1][0] == 'D' and history[-1][1] == 'D' and
            history[-2][0] == 'D' and history[-2][1] == 'D'):
            return 'C'

    if n < 4:
        opD = sum(1 for h in history if h[1] == 'D')
        if opD == 0:
            return 'C'
        if opD == n:
            return 'D'
        return 'C'

    if history[-1][1] == 'D':
        return 'D'
    return 'C'
